-- Owner's starter narration setup (12.11.2026), seeded like the starter templates: each part ONLY
-- when it is not set yet, then edited in Settings as before. Nothing here enables auto narration.
--  * voices: the owner's eight ElevenLabs voices (names and gender from the owner);
--  * modelId: eleven_v4 (the model with Tajik, FACT checked on the API 12.11.2026);
--  * voiceSettings: stability 0.5, similarity_boost 0.75, speed 1.0 (owner's values; style and
--    speaker boost are not sent to v4, see narrationTtsOptions);
--  * pronunciationRules: 70 Tajik words that have an alias or IPA phoneme; "needsNative" marks
--    words still to be checked by a native speaker (shown in Settings).
WITH cfg AS (SELECT COALESCE("propertyNarrationConfig", '{}'::jsonb) AS c FROM "Settings" WHERE "id" = 'singleton')
UPDATE "Settings" s
SET "propertyNarrationConfig" = (
  SELECT cfg.c
    || CASE WHEN jsonb_typeof(cfg.c->'voices') = 'array' AND jsonb_array_length(cfg.c->'voices') > 0 THEN '{}'::jsonb
            ELSE jsonb_build_object('voices', $json$[{"id": "BE01v3e9mZOvL75SsISY", "name": "Nataly Vershinina", "gender": "female"}, {"id": "xcVbjGhhLIoKi3va6mAe", "name": "Viktoriya Voloshina", "gender": "female"}, {"id": "r1KmysJdVYZjJCm4mL3b", "name": "Jessica", "gender": "female"}, {"id": "kPzsL2i3teMYv0FxEYQ6", "name": "Brittney", "gender": "female"}, {"id": "XuEV9VY3VUASYgJVNBh0", "name": "Sergey", "gender": "male"}, {"id": "M1CSR3PJBsfWU6ZquG3C", "name": "Denophine", "gender": "male"}, {"id": "wBXNqKUATyqu0RtYt25i", "name": "Adam", "gender": "male"}, {"id": "yl2ZDV1MzN4HbQJbMihG", "name": "Alex", "gender": "male"}]$json$::jsonb) END
    || CASE WHEN COALESCE(cfg.c->>'modelId', '') <> '' THEN '{}'::jsonb ELSE '{"modelId": "eleven_v4"}'::jsonb END
    || CASE WHEN cfg.c ? 'voiceSettings' THEN '{}'::jsonb
            ELSE '{"voiceSettings": {"stability": 0.5, "similarityBoost": 0.75, "speed": 1.0}}'::jsonb END
    || CASE WHEN cfg.c ? 'pronunciationRules' THEN '{}'::jsonb
            ELSE jsonb_build_object('pronunciationRules', $json$[{"word": "ҳавлӣ", "phoneme": "/havˈli/", "needsNative": true}, {"word": "ҳуҷра", "phoneme": "/hudʒˈra/", "needsNative": true}, {"word": "ҳуҷраҳо", "phoneme": "/hudʒraˈhɔ/", "needsNative": true}, {"word": "ошёна", "phoneme": "/ɔʃjɔˈna/", "needsNative": true}, {"word": "масоҳат", "phoneme": "/masɔˈhat/", "needsNative": true}, {"word": "таъмир", "phoneme": "/taʔˈmir/", "needsNative": true}, {"word": "нарх", "phoneme": "/ˈnarχ/", "needsNative": true}, {"word": "фурӯш", "phoneme": "/fuˈroʃ/", "needsNative": true}, {"word": "иҷора", "phoneme": "/idʒɔˈra/", "needsNative": true}, {"word": "ошхона", "phoneme": "/ɔʃχɔˈna/", "needsNative": true}, {"word": "ҳаммом", "phoneme": "/hamˈmɔm/", "needsNative": true}, {"word": "ҳуҷҷат", "phoneme": "/hudʒˈdʒat/", "needsNative": true}, {"word": "сомонӣ", "phoneme": "/sɔmɔˈni/", "needsNative": true}, {"word": "ноҳия", "phoneme": "/nɔˈhiя/", "needsNative": true}, {"word": "суроға", "phoneme": "/surɔˈʁa/", "needsNative": true}, {"word": "хона", "phoneme": "/χɔˈna/", "needsNative": true}, {"word": "бино", "phoneme": "/biˈnɔ/", "needsNative": true}, {"word": "м²", "alias": "метри мураббаъ"}, {"word": "кв.м", "alias": "метри мураббаъ"}, {"word": "кв. м", "alias": "метри мураббаъ"}, {"word": "$", "alias": "доллар"}, {"word": "USD", "alias": "доллар"}, {"word": "TJS", "alias": "сомонӣ"}, {"word": "мкр", "alias": "микрорайон", "needsNative": true}, {"word": "Royal Home", "alias": "Роял Хом"}, {"word": "Royal", "alias": "Роял"}, {"word": "Роял Хом", "alias": "Роял Хом"}, {"word": "1", "alias": "як"}, {"word": "2", "alias": "ду"}, {"word": "3", "alias": "се"}, {"word": "4", "alias": "чор"}, {"word": "5", "alias": "панҷ"}, {"word": "6", "alias": "шаш"}, {"word": "7", "alias": "ҳафт"}, {"word": "8", "alias": "ҳашт"}, {"word": "9", "alias": "нӯҳ"}, {"word": "10", "alias": "даҳ"}, {"word": "20", "alias": "бист"}, {"word": "30", "alias": "сӣ"}, {"word": "40", "alias": "чил"}, {"word": "50", "alias": "панҷоҳ", "needsNative": true}, {"word": "60", "alias": "шаст"}, {"word": "70", "alias": "ҳафтод", "needsNative": true}, {"word": "80", "alias": "ҳаштод", "needsNative": true}, {"word": "90", "alias": "навад", "needsNative": true}, {"word": "100", "alias": "сад"}, {"word": "1000", "alias": "ҳазор"}, {"word": "60 000", "alias": "шаст ҳазор"}, {"word": "82", "alias": "ҳаштоду ду", "needsNative": true}, {"word": "92", "alias": "наваду ду", "needsNative": true}, {"word": "101", "alias": "саду як", "needsNative": true}, {"word": "102", "alias": "саду ду", "needsNative": true}, {"word": "103", "alias": "саду се", "needsNative": true}, {"word": "104", "alias": "саду чор", "needsNative": true}, {"word": "Сино", "phoneme": "/siˈnɔ/", "needsNative": true}, {"word": "Фирдавсӣ", "phoneme": "/firdavˈsi/", "needsNative": true}, {"word": "Шоҳмансур", "phoneme": "/ʃɔhmanˈsur/", "needsNative": true}, {"word": "Шохмансур", "alias": "Шоҳмансур"}, {"word": "Зарафшон", "phoneme": "/zarafˈʃɔn/", "needsNative": true}, {"word": "Садбарг", "phoneme": "/sadˈbarɡ/", "needsNative": true}, {"word": "Ватан", "phoneme": "/vaˈtan/", "needsNative": true}, {"word": "Душанбе-сити", "alias": "Душанбе Сити", "needsNative": true}, {"word": "Ваҳдат", "phoneme": "/vahˈdat/", "needsNative": true}, {"word": "Ҳисор", "phoneme": "/hiˈsɔr/", "needsNative": true}, {"word": "Рӯдакӣ", "phoneme": "/rodaˈki/", "needsNative": true}, {"word": "Варзоб", "phoneme": "/varˈzɔb/", "needsNative": true}, {"word": "Душанбе", "phoneme": "/duʃanˈbe/", "needsNative": true}, {"word": "Бохтар", "phoneme": "/bɔχˈtar/", "needsNative": true}, {"word": "субҳ", "phoneme": "/ˈsubh/", "needsNative": true}, {"word": "ошёнаи", "phoneme": "/ɔʃjɔnaˈi/", "needsNative": true}]$json$::jsonb) END
  FROM cfg
)
WHERE s."id" = 'singleton';
